package com.pablo.controlgastos;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;
public class CreditCardDb extends SQLiteOpenHelper{
 public CreditCardDb(Context c){super(c,"credit_cards.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE cards(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,last4 TEXT UNIQUE)");d.execSQL("CREATE TABLE statements(id INTEGER PRIMARY KEY AUTOINCREMENT,card_id INTEGER,close_date TEXT,due_date TEXT,total REAL,currency TEXT,UNIQUE(card_id,close_date,currency))");d.execSQL("CREATE TABLE installments(id INTEGER PRIMARY KEY AUTOINCREMENT,statement_id INTEGER,tx_date TEXT,description TEXT,installment TEXT,amount REAL,currency TEXT)");}public void onUpgrade(SQLiteDatabase d,int o,int n){}
 public long card(String name,String last4){SQLiteDatabase d=getWritableDatabase();ContentValues v=new ContentValues();v.put("name",name);v.put("last4",last4);d.insertWithOnConflict("cards",null,v,SQLiteDatabase.CONFLICT_IGNORE);Cursor c=d.rawQuery("SELECT id FROM cards WHERE last4=?",new String[]{last4});try{return c.moveToFirst()?c.getLong(0):-1;}finally{c.close();}}
 public long statement(long card,String close,String due,double total,String cur){SQLiteDatabase d=getWritableDatabase();ContentValues v=new ContentValues();v.put("card_id",card);v.put("close_date",close);v.put("due_date",due);v.put("total",total);v.put("currency",cur);d.insertWithOnConflict("statements",null,v,SQLiteDatabase.CONFLICT_REPLACE);Cursor c=d.rawQuery("SELECT id FROM statements WHERE card_id=? AND close_date=? AND currency=?",new String[]{""+card,close,cur});try{return c.moveToFirst()?c.getLong(0):-1;}finally{c.close();}}
 public void clearItems(long s){getWritableDatabase().delete("installments","statement_id=?",new String[]{""+s});}public void item(long s,String date,String desc,String inst,double amount,String cur){ContentValues v=new ContentValues();v.put("statement_id",s);v.put("tx_date",date);v.put("description",desc);v.put("installment",inst);v.put("amount",amount);v.put("currency",cur);getWritableDatabase().insert("installments",null,v);}
}